1025	// Tail activation count in T-elements (after all layers).
1026	template <typename T>
1027	__host__ inline size_t tail_act_elems(int rows, int batch, int d_model) {
1028	    size_t n = 0;
1029	    n += floats_as_T<T>(rows);                       // mean_lnf
1030	    n += floats_as_T<T>(rows);                       // rstd_lnf
1031	    n += (size_t)batch * d_model;                    // last_save
1032	    return n;
1033	}
