1035	// Total activation cache size in T-elements.
1036	template <typename T>
1037	__host__ inline size_t activation_cache_elems(
1038	    int batch, int seq_len, int d_model, int d_state, int expand, int n_layers)
1039	{
1040	    const int rows    = batch * seq_len;
1041	    const int d_inner = d_model * expand;
1042	    const int dt_rank = std::max(d_model / 16, 1);
1043	    size_t pla = per_layer_act_elems<T>(rows, d_model, d_inner, dt_rank, d_state);
1044	    size_t tail = tail_act_elems<T>(rows, batch, d_model);
1045	    return (size_t)n_layers * pla + tail;
1046	}
