1048	// ─────────────────────────────────────────────────────────────────────
1049	//  Struct for layer activation pointers (resolved from cache buffer).
1050	// ─────────────────────────────────────────────────────────────────────
1051	
1052	template <typename T>
1053	struct LayerActPtrs {
1054	    T*      h_pre;          // [rows, d_model]
1055	    float*  mean_ln1;       // [rows]
1056	    float*  rstd_ln1;       // [rows]
1057	    T*      x_main_save;    // [rows, d_inner]
1058	    T*      z_save;         // [rows, d_inner]
1059	    T*      xc_save;        // [rows, d_inner]
1060	    T*      dt_pre_save;    // [rows, dt_rank]
1061	    T*      dt_full_save;   // [rows, d_inner]
1062	    T*      B_save;         // [rows, d_state]
1063	    T*      C_save;         // [rows, d_state]
1064	    T*      y_scan_save;    // [rows, d_inner]
1065	    float*  mean_ln2;       // [rows]
1066	    float*  rstd_ln2;       // [rows]
1067	    T*      h_post_save;    // [rows, d_model]
1068	};
1069	
1070	template <typename T>
1071	__host__ inline LayerActPtrs<T> resolve_layer_act(
1072	    T* base, int l,
1073	    int rows, int d_model, int d_inner, int dt_rank, int d_state)
1074	{
1075	    size_t pla = per_layer_act_elems<T>(rows, d_model, d_inner, dt_rank, d_state);
1076	    T* p = base + (size_t)l * pla;
1077	    LayerActPtrs<T> A;
1078	    A.h_pre       = p; p += (size_t)rows * d_model;
1079	    A.mean_ln1    = reinterpret_cast<float*>(p); p += floats_as_T<T>(rows);
1080	    A.rstd_ln1    = reinterpret_cast<float*>(p); p += floats_as_T<T>(rows);
1081	    A.x_main_save = p; p += (size_t)rows * d_inner;
1082	    A.z_save      = p; p += (size_t)rows * d_inner;
1083	    A.xc_save     = p; p += (size_t)rows * d_inner;
1084	    A.dt_pre_save = p; p += (size_t)rows * dt_rank;
1085	    A.dt_full_save= p; p += (size_t)rows * d_inner;
1086	    A.B_save      = p; p += (size_t)rows * d_state;
1087	    A.C_save      = p; p += (size_t)rows * d_state;
1088	    A.y_scan_save = p; p += (size_t)rows * d_inner;
1089	    A.mean_ln2    = reinterpret_cast<float*>(p); p += floats_as_T<T>(rows);
1090	    A.rstd_ln2    = reinterpret_cast<float*>(p); p += floats_as_T<T>(rows);
1091	    A.h_post_save = p;
1092	    return A;
1093	}
