1095	// Resolve tail activation pointers (after all n_layers).
1096	template <typename T>
1097	struct TailActPtrs {
1098	    float* mean_lnf;    // [rows]
1099	    float* rstd_lnf;    // [rows]
1100	    T*     last_save;   // [batch, d_model]
1101	};
1102	
1103	template <typename T>
1104	__host__ inline TailActPtrs<T> resolve_tail_act(
1105	    T* base, int n_layers,
1106	    int rows, int batch, int d_model, int d_inner, int dt_rank, int d_state)
1107	{
1108	    size_t pla = per_layer_act_elems<T>(rows, d_model, d_inner, dt_rank, d_state);
1109	    T* p = base + (size_t)n_layers * pla;
1110	    TailActPtrs<T> A;
1111	    A.mean_lnf  = reinterpret_cast<float*>(p); p += floats_as_T<T>(rows);
1112	    A.rstd_lnf  = reinterpret_cast<float*>(p); p += floats_as_T<T>(rows);
1113	    A.last_save = p;
1114	    return A;
1115	}
