1117	// ─────────────────────────────────────────────────────────────────────
1118	//  Forward pass — full Mamba stack. The `input` parameter is interpreted
1119	//  as a buffer of int32 token ids (B*N) cast to T*. The binding ensures
1120	//  the underlying tensor is int32 and reinterprets safely.
1121	//
1122	//  `states` serves dual purpose:
1123	//    1. Transient workspace for per-layer intermediate buffers (reused
1124	//       across layers for the non-caching path).
1125	//    2. When `activation_cache` is non-null (or when `states` is large
1126	//       enough to hold the activation section), per-layer activations
1127	//       are saved for the backward pass. The binding passes the same
1128	//       `states` tensor to backward as `activations_saved`.
1129	//
1130	//  CONTRACT: `states` must be sized to hold BOTH the transient workspace
1131	//  AND the activation cache. Use activation_cache_elems<T>(...) to
1132	//  compute the extra elements needed after the transient workspace.
1133	//  The transient workspace size (in T-elems) is approximately:
1134	//    rows*(2*d_model + 2*d_inner*4 + dt_rank + d_state*2) + B*d_inner*d_state
1135	//  (see exact layout below). The binding allocates conservatively.
1136	// ─────────────────────────────────────────────────────────────────────
1137	
1138	template <typename T>
1139	cudaError_t forward(
1140	    const T* input,                  // reinterpret as int32* (B*N ids)
1141	    const T* weights,
1142	    T* output,                       // [B, p_vocab]  (last-token logits)
1143	    T* states,                       // workspace + activation save area
1144	    int batch, int seq_len, int d_model, int d_state,
1145	    int d_conv, int expand, int n_layers,
1146	    cudaStream_t stream,
1147	    T* activation_cache = nullptr)   // if non-null, save activations here;
1148	                                     // if null, save into states after workspace
1149	{
1150	    (void)d_conv;  // we hard-code k=3, pad=1 per Python ref
1151	    const int d_inner = d_model * expand;
1152	    const int dt_rank = std::max(d_model / 16, 1);
1153	    const int vocab   = 99;   // grokking config (used only for embedding bound)
1154	    const int rows    = batch * seq_len;
1155	    const float eps   = 1e-5f;
1156	
1157	    auto handle = at::cuda::getCurrentCUDABlasHandle();
1158	    cublasSetStream(handle, stream);
1159	
1160	    // Transient workspace partition (all in-place over `states`):
1161	    //   h        [B, N, d_model]
1162	    //   res      [B, N, d_model]      (for residual save)
1163	    //   xz       [B, N, 2*d_inner]
1164	    //   x_main   [B, N, d_inner]
1165	    //   z        [B, N, d_inner]
1166	    //   xc       [B, N, d_inner]      (post-conv-silu)
1167	    //   x_dbc    [B, N, dt_rank+2*d_state]
1168	    //   dt_pre   [B, N, dt_rank]
1169	    //   dt_full  [B, N, d_inner]      (post-dt_proj+softplus)
1170	    //   B_buf    [B, N, d_state]
1171	    //   C_buf    [B, N, d_state]
1172	    //   y_scan   [B, N, d_inner]
1173	    //   state_save [B, d_inner, d_state] float   (scan recurrence state)
1174	
1175	    T* w = states;
1176	    T* h        = w; w += (size_t)rows * d_model;
1177	    T* res      = w; w += (size_t)rows * d_model;
1178	    T* xz       = w; w += (size_t)rows * 2 * d_inner;
1179	    T* x_main   = w; w += (size_t)rows * d_inner;
1180	    T* z_buf    = w; w += (size_t)rows * d_inner;
1181	    T* xc       = w; w += (size_t)rows * d_inner;
1182	    T* x_dbc    = w; w += (size_t)rows * (dt_rank + 2 * d_state);
1183	    T* dt_pre   = w; w += (size_t)rows * dt_rank;
1184	    T* dt_full  = w; w += (size_t)rows * d_inner;
1185	    T* B_buf    = w; w += (size_t)rows * d_state;
1186	    T* C_buf    = w; w += (size_t)rows * d_state;
1187	    T* y_scan   = w; w += (size_t)rows * d_inner;
1188	    // scan recurrence state (float) lives at `w`; we keep it as float*
1189	    float* state_save = reinterpret_cast<float*>(w);
1190	    // advance w past state_save (B*d_inner*d_state floats, rounded to T)
1191	    w += floats_as_T<T>((size_t)batch * d_inner * d_state);
1192	
1193	    // Activation cache: use caller-provided pointer or fall back to states
1194	    // immediately after the transient workspace.
1195	    T* act_base = (activation_cache != nullptr) ? activation_cache : w;
1196	
1197	    // 1. Embedding
1198	    {
1199	        const int* ids = reinterpret_cast<const int*>(input);
1200	        dim3 grid(seq_len, batch);
1201	        int block = std::min(d_model, 256);
1202	        embed_kernel<T><<<grid, block, 0, stream>>>(
1203	            ids, weights /*tok_emb*/, weights + (size_t)vocab * d_model /*pos_emb*/,
1204	            h, batch, seq_len, d_model, vocab);
1205	        SG_LAUNCH_CHECK(stream);
1206	    }
1207	
1208	    // 2. Per-layer
1209	    for (int l = 0; l < n_layers; l++) {
1210	        WeightPtrs<T> W;
1211	        resolve_layer<T>(weights, l, n_layers, vocab, seq_len,
1212	                         d_model, d_inner, d_state, dt_rank, W);
1213	
1214	        // Resolve activation save pointers for this layer.
1215	        LayerActPtrs<T> A = resolve_layer_act<T>(
1216	            act_base, l, rows, d_model, d_inner, dt_rank, d_state);
1217	
1218	        // Save h_pre (layer input, before any transformation).
1219	        // This is the residual that gets added back after out_proj.
1220	        cudaMemcpyAsync(A.h_pre, h, (size_t)rows * d_model * sizeof(T),
1221	                        cudaMemcpyDeviceToDevice, stream);
1222	        // Zero mean_ln1/rstd_ln1 (unused — ln1 weights are reserved but not applied
1223	        // in the current forward formulation; backward skips LN1 accordingly).
1224	        // We mark them invalid by leaving them at 0 (from the activation cache memset).
1225	
1226	        // Save residual = h_pre for the add_residual_kernel at the end of the layer.
1227	        cudaMemcpyAsync(res, h, (size_t)rows * d_model * sizeof(T),
1228	                        cudaMemcpyDeviceToDevice, stream);
1229	
1230	        // (a) in_proj GEMM:  xz [rows, 2*d_inner] = h_ln1 [rows, d_model] · in_proj_W^T
1231	        cudaError_t err = gemm_rowmajor_NT<T>(handle, rows, 2 * d_inner, d_model,
1232	                                              h, W.in_proj_W, xz, stream);
1233	        if (err != cudaSuccess) return err;
1234	
1235	        // (b) split xz -> x_main, z
1236	        {
1237	            dim3 grid(rows, (d_inner + 127) / 128);
1238	            split_chunk2_kernel<T><<<grid, 128, 0, stream>>>(xz, x_main, z_buf, rows, d_inner);
1239	            SG_LAUNCH_CHECK(stream);
1240	        }
1241	
1242	        // Save x_main and z before conv/gate (needed for backward).
1243	        cudaMemcpyAsync(A.x_main_save, x_main, (size_t)rows * d_inner * sizeof(T),
1244	                        cudaMemcpyDeviceToDevice, stream);
1245	        cudaMemcpyAsync(A.z_save, z_buf, (size_t)rows * d_inner * sizeof(T),
1246	                        cudaMemcpyDeviceToDevice, stream);
1247	
1248	        // (c) conv1d depthwise k=3 pad=1 + SiLU
1249	        {
1250	            dim3 grid((d_inner + 127) / 128, seq_len, batch);
1251	            conv1d_silu_kernel<T><<<grid, 128, 0, stream>>>(
1252	                x_main, W.conv_W, W.conv_b, xc,
1253	                batch, seq_len, d_inner);
1254	            SG_LAUNCH_CHECK(stream);
1255	        }
1256	
1257	        // Save xc (post-conv-silu).
1258	        cudaMemcpyAsync(A.xc_save, xc, (size_t)rows * d_inner * sizeof(T),
1259	                        cudaMemcpyDeviceToDevice, stream);
1260	
1261	        // (d) x_proj GEMM: x_dbc [rows, dt_rank+2*d_state] = xc · x_proj_W^T
1262	        err = gemm_rowmajor_NT<T>(handle, rows, dt_rank + 2 * d_state, d_inner,
1263	                                  xc, W.x_proj_W, x_dbc, stream);
1264	        if (err != cudaSuccess) return err;
1265	
1266	        // (e) split x_dbc -> dt_pre, B_buf, C_buf
1267	        {
1268	            dim3 grid(rows, (dt_rank + 2 * d_state + 127) / 128);
1269	            split_dbc_kernel<T><<<grid, 128, 0, stream>>>(
1270	                x_dbc, dt_pre, B_buf, C_buf, rows, dt_rank, d_state);
1271	            SG_LAUNCH_CHECK(stream);
1272	        }
1273	
1274	        // Save dt_pre, B, C.
1275	        cudaMemcpyAsync(A.dt_pre_save, dt_pre, (size_t)rows * dt_rank * sizeof(T),
1276	                        cudaMemcpyDeviceToDevice, stream);
1277	        cudaMemcpyAsync(A.B_save, B_buf, (size_t)rows * d_state * sizeof(T),
1278	                        cudaMemcpyDeviceToDevice, stream);
1279	        cudaMemcpyAsync(A.C_save, C_buf, (size_t)rows * d_state * sizeof(T),
1280	                        cudaMemcpyDeviceToDevice, stream);
1281	
1282	        // (f) dt_proj GEMM + softplus(+ bias).  dt_full = dt_pre · dt_proj_W^T
1283	        err = gemm_rowmajor_NT<T>(handle, rows, d_inner, dt_rank,
1284	                                  dt_pre, W.dt_proj_W, dt_full, stream);
1285	        if (err != cudaSuccess) return err;
1286	        {
1287	            int block = 256;
1288	            int grid  = (rows * d_inner + block - 1) / block;
1289	            softplus_bias_kernel<T><<<grid, block, 0, stream>>>(dt_full, W.dt_proj_b, rows, d_inner);
1290	            SG_LAUNCH_CHECK(stream);
1291	        }
1292	
1293	        // Save dt_full (post-softplus).
1294	        cudaMemcpyAsync(A.dt_full_save, dt_full, (size_t)rows * d_inner * sizeof(T),
1295	                        cudaMemcpyDeviceToDevice, stream);
1296	
1297	        // (g) selective scan via adapter
1298	        err = mamba_adapter::selective_scan_forward<T>(
1299	            xc, dt_full, W.A_log, B_buf, C_buf,
1300	            y_scan, state_save,
1301	            batch, seq_len, d_inner, d_state, stream);
1302	        if (err != cudaSuccess) return err;
1303	
1304	        // Save y_scan BEFORE the gate (gate modifies y_scan in-place).
1305	        cudaMemcpyAsync(A.y_scan_save, y_scan, (size_t)rows * d_inner * sizeof(T),
1306	                        cudaMemcpyDeviceToDevice, stream);
1307	
1308	        // (h) y = (y + x_main_post_silu * D) * SiLU(z)
1309	        //     where the "x_main * D" skip uses the post-conv-SiLU xc per Python ref.
1310	        {
1311	            dim3 grid(rows, (d_inner + 127) / 128);
1312	            gate_dskip_kernel<T><<<grid, 128, 0, stream>>>(
1313	                y_scan, xc, W.D, z_buf, rows, d_inner);
1314	            SG_LAUNCH_CHECK(stream);
1315	        }
1316	
1317	        // (i) out_proj GEMM:  h_new = y_gated · out_proj_W^T  [rows, d_model]
1318	        err = gemm_rowmajor_NT<T>(handle, rows, d_model, d_inner,
1319	                                  y_scan, W.out_proj_W, h, stream);
1320	        if (err != cudaSuccess) return err;
1321	
1322	        // (j) Add residual (h_pre)
1323	        {
1324	            int64_t n = static_cast<int64_t>(rows) * d_model;
1325	            int block = 256;
1326	            int grid  = static_cast<int>((n + block - 1) / block);
1327	            add_residual_kernel<T><<<grid, block, 0, stream>>>(h, res, n);
1328	            SG_LAUNCH_CHECK(stream);
1329	        }
1330	
1331	        // (k) LayerNorm 2 (post-block): save h (post-residual) as h_post_save,
1332	        //     then apply LN2 in-place and record statistics.
1333	        cudaMemcpyAsync(A.h_post_save, h, (size_t)rows * d_model * sizeof(T),
1334	                        cudaMemcpyDeviceToDevice, stream);
1335	        {
1336	            int block = 128;
1337	            size_t smem = 2 * block * sizeof(float);
1338	            layernorm_kernel<T><<<rows, block, smem, stream>>>(
1339	                h, W.ln2_g, W.ln2_b, h,
1340	                A.mean_ln2, A.rstd_ln2, d_model, eps);
1341	            SG_LAUNCH_CHECK(stream);
1342	        }
1343	    }
1344	
1345	    // 3. Final LayerNorm + head
1346	    WeightPtrs<T> Wlast;
1347	    resolve_layer<T>(weights, 0, n_layers, vocab, seq_len,
1348	                     d_model, d_inner, d_state, dt_rank, Wlast);
1349	    TailActPtrs<T> Atail = resolve_tail_act<T>(
1350	        act_base, n_layers, rows, batch, d_model, d_inner, dt_rank, d_state);
1351	    {
1352	        int block = 128;
1353	        size_t smem = 2 * block * sizeof(float);
1354	        layernorm_kernel<T><<<rows, block, smem, stream>>>(
1355	            h, Wlast.ln_final_g, Wlast.ln_final_b, h,
1356	            Atail.mean_lnf, Atail.rstd_lnf, d_model, eps);
1357	        SG_LAUNCH_CHECK(stream);
1358	    }
1359	
1360	    // Gather last token: last [B, d_model] = h[:, N-1, :]
1361	    // Save into tail activation cache (not state_save, which is scan state).
1362	    {
1363	        dim3 grid(batch, (d_model + 127) / 128);
1364	        gather_last_token_kernel<T><<<grid, 128, 0, stream>>>(
1365	            h, Atail.last_save, batch, seq_len, d_model);
1366	        SG_LAUNCH_CHECK(stream);
1367	    }
1368	
1369	    // Head GEMM: output [B, p_vocab] = last [B, d_model] · head_W^T [p_vocab, d_model]
1370	    int p_vocab = 97;   // grokking default
1371	    cudaError_t err = gemm_rowmajor_NT<T>(handle, batch, p_vocab, d_model,
1372	                                          Atail.last_save, Wlast.head_W, output, stream);
1373	    return err;
1374	}
