1376	// ─────────────────────────────────────────────────────────────────────
1377	//  Backward pass — REAL fused reverse pass.
1378	//
1379	//  Processes the full N-layer Mamba stack in reverse order, computing
1380	//  exact gradients for all weight parameters using per-layer activations
1381	//  saved during forward(). The activation layout in activations_saved
1382	//  matches the layout written by forward() into the states buffer.
1383	//
1384	//  grad_input stays zero (gradient w.r.t. integer token ids is undefined).
1385	//
1386	//  Gradient accumulators for weights are maintained as float buffers
1387	//  internally and converted to T at the end for each parameter. Weight
1388	//  gradient GEMMs use cuBLAS via ATen's handle (beta=1.0 to accumulate).
1389	//
1390	//  The selective scan backward uses mamba_adapter::selective_scan_backward
1391	//  which implements the full adjoint scan (forward-recompute + reverse pass).
1392	// ─────────────────────────────────────────────────────────────────────
1393	
1394	template <typename T>
1395	cudaError_t backward(
1396	    const T* grad_output,            // [B, p_vocab] loss gradient
1397	    const T* activations_saved,      // per-layer activations saved by forward()
1398	    const T* weights,
1399	    T* grad_input,                   // [B*N] — zero (grad w.r.t. token ids)
1400	    T* grad_weights,                 // [total_weight_elems] accumulated grads
1401	    int batch, int seq_len, int d_model, int d_state,
1402	    int d_conv, int expand, int n_layers,
1403	    cudaStream_t stream)
1404	{
1405	    (void)d_conv;
1406	    const int d_inner  = d_model * expand;
1407	    const int dt_rank  = std::max(d_model / 16, 1);
1408	    const int vocab    = 99;
1409	    const int p_vocab  = 97;
1410	    const int rows     = batch * seq_len;
1411	    const float eps    = 1e-5f;
1412	
1413	    auto handle = at::cuda::getCurrentCUDABlasHandle();
1414	    cublasSetStream(handle, stream);
1415	
1416	    // ── Zero grad_input ──────────────────────────────────────────────
1417	    if (grad_input) {
1418	        cudaMemsetAsync(grad_input, 0,
1419	            (size_t)batch * seq_len * sizeof(T), stream);
1420	    }
1421	    if (!grad_weights) return cudaGetLastError();
1422	
1423	    // ── Compute total weight buffer size and zero grad_weights ───────
1424	    size_t total_w = 0;
1425	    total_w += (size_t)vocab * d_model;           // tok_emb
1426	    total_w += (size_t)seq_len * d_model;         // pos_emb
1427	    total_w += (size_t)n_layers *
1428	               per_layer_count<T>(d_model, d_inner, d_state, dt_rank);
1429	    total_w += (size_t)2 * d_model;               // ln_final g,b
1430	    total_w += (size_t)p_vocab * d_model;         // head_W
