2033	//  selective_scan_fwd / bwd : thin component-test wrappers around the
2034	//  adapter. The binding signature has only 4 inputs (u, delta, A, B) and
2035	//  2 outputs (out, state) — for component testing we set d_inner = d_state
2036	//  and use B as both B and C. This matches the simple "minimal scan" test.
2037	// ─────────────────────────────────────────────────────────────────────
2038	
2039	template <typename T>
2040	cudaError_t selective_scan_fwd(
2041	    const T* u, const T* delta, const T* A, const T* B,
2042	    T* out, T* state,
2043	    int batch, int seq_len, int d_state, cudaStream_t stream)
2044	{
2045	    // Component-test wrapper: d_inner == d_state, C == B.
2046	    float* state_f = reinterpret_cast<float*>(state);
2047	    return mamba_adapter::selective_scan_forward<T>(
2048	        u, delta, A, B, B, out, state_f,
2049	        batch, seq_len, /*d_inner=*/d_state, d_state, stream);
2050	}
2051	
2052	template <typename T>
2053	cudaError_t selective_scan_bwd(
2054	    const T* grad_out,
2055	    const T* u, const T* delta, const T* A,
2056	    const T* B, const T* state,
2057	    T* grad_u, T* grad_delta, T* grad_A, T* grad_B,
2058	    int batch, int seq_len, int d_state, cudaStream_t stream)
2059	{
2060	    // Component-test wrapper. Caller should allocate `state` and `grad_A`
2061	    // as FP32 buffers regardless of T (the adapter operates in FP32 for the
2062	    // recurrence) — we reinterpret accordingly. d_inner == d_state and
2063	    // C := B (so grad_C aliases grad_B).
2064	    const float* state_f = reinterpret_cast<const float*>(state);
2065	    float* grad_A_f      = reinterpret_cast<float*>(grad_A);
2066	    return mamba_adapter::selective_scan_backward<T>(
2067	        grad_out, u, delta, A, B, B, state_f,
2068	        grad_u, grad_delta, grad_A_f, grad_B, grad_B,
2069	        batch, seq_len, /*d_inner=*/d_state, d_state, stream);
2070	}
